        (20, r"\lim_{n \to \infty} \frac{5n^2-2n}{2n^2+1}\text{의 값은?}", "\\frac{5}{2}", ["1", "2", "3", "\\frac{7}{2}"], r"극한값은 $\frac{5}{2}$입니다.", ""),
