        (9, r"\lim_{n \to \infty} (\sqrt{n^2+8n}-n)\text{의 값은?}", "4", ["1", "2", "3", "5"], r"2016학년도 모의평가: $\frac{8n}{\sqrt{n^2+8n}+n} \to 4$", "2016학년도 모의평가"),
        (10, r"\lim_{n \to \infty} (\sqrt{n^2+28n}-n)\text{의 값을 구하시오.}", "14", [], r"2017학년도 수능: $\frac{28n}{\sqrt{n^2+28n}+n} = 14$", "2017학년도 수능"),
