        (12, r"\lim_{n \to \infty} (\sqrt{9n^2+6n}-3n)\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"2018학년도 모의평가: $\frac{6n}{\sqrt{9n^2+6n}+3n} = \frac{6}{6} = 1$", "2018학년도 모의평가"),
        (13, r"\lim_{n \to \infty} (\sqrt{n^2+10n}-n)\text{의 값은?}", "5", ["2", "3", "4", "6"], r"극한값은 $\frac{10}{2} = 5$입니다.", ""),
        (14, r"\lim_{n \to \infty} (\sqrt{n^2+an}-n) = 3\text{일 때, 상수 } a\text{의 값은?}", "6", ["2", "4", "8", "10"], r"$\frac{a}{2} = 3 \implies a = 6$", ""),
