        (9, r"\lim_{n \to \infty} \frac{5^{n+1}-2^n}{5^n+3}\text{의 값은?}", "5", ["1", "2", "3", "4"], r"2015학년도 수능: $5$", "2015학년도 수능"),
        (10, r"\lim_{n \to \infty} \frac{4 \cdot 3^{n+1}+1}{3^n-2}\text{의 값은?}", "12", ["3", "4", "6", "9"], r"2016학년도 수능: $4 \times 3 = 12$", "2016학년도 수능"),
        (11, r"\lim_{n \to \infty} \frac{3^{n+2}+2}{3^n+1}\text{의 값은?}", "9", ["1", "3", "6", "12"], r"2017학년도 모의평가: $3^2 = 9$", "2017학년도 모의평가"),
        (12, r"\lim_{n \to \infty} \frac{2^{n+3}+1}{2^n+5}\text{의 값은?}", "8", ["2", "4", "6", "10"], r"2017학년도 수능: $2^3 = 8$", "2017학년도 수능"),
        (13, r"\lim_{n \to \infty} \frac{5^{n+1}+3}{5^n-2^n}\text{의 값은?}", "5", ["1", "2", "3", "4"], r"2018학년도 모의평가: $5$", "2018학년도 모의평가"),
        (14, r"\lim_{n \to \infty} \frac{3^{n+1}-2^n}{3^n+1}\text{의 값은?}", "3", ["1", "2", "4", "5"], r"2018학년도 수능: $3$", "2018학년도 수능"),
        (15, r"\lim_{n \to \infty} \frac{3 \cdot 5^{n+1}+2}{5^n+1}\text{의 값을 구하시오.}", "15", [], r"2016학년도 모의평가: $3 \times 5 = 15$", "2016학년도 모의평가"),
        (16, r"\lim_{n \to \infty} \frac{2 \cdot 4^n + 3^n}{4^{n-1}+1}\text{의 값은?}", "8", ["2", "4", "6", "10"], r"$$\frac{2}{\frac{1}{4}} = 8$$", ""),
        (17, r"\lim_{n \to \infty} \frac{a \cdot 3^{n+1}+2^n}{3^n+5} = 6\text{일 때, } a\text{의 값은?}", "2", ["1", "3", "4", "5"], r"$3a = 6 \implies a = 2$", ""),
        (18, r"\lim_{n \to \infty} \frac{4^{n+1}+3^n}{4^n-2^n}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"극한값은 $4$입니다.", ""),
        (19, r"\lim_{n \to \infty} \frac{7^{n+1}+2}{7^n-3^n}\text{의 값은?}", "7", ["1", "3", "5", "9"], r"극한값은 $7$입니다.", ""),
        (20, r"\lim_{n \to \infty} \frac{5 \cdot 2^{n+1}-3}{2^n+1}\text{의 값은?}", "10", ["2", "4", "6", "8"], r"$5 \times 2 = 10$", ""),
        (21, r"\lim_{n \to \infty} \frac{3 \cdot 5^n + 2^n}{5^{n-1}+3}\text{의 값을 구하시오.}", "15", [], r"$$\frac{3}{\frac{1}{5}} = 15$$", ""),
        (22, r"\lim_{n \to \infty} \frac{2^{2n+1}+1}{4^n+3}\text{의 값은?}", "2", ["1", "3", "4", "5"], r"$2^{2n+1} = 2 \cdot 4^n$이므로 극한값은 $2$입니다.", ""),
        (23, r"\lim_{n \to \infty} \frac{3^{2n}-1}{9^n+2^n}\text{의 값은?}", "1", ["0", "2", "3", "9"], r"$3^{2n} = 9^n$이므로 극한값은 $1$입니다.", ""),
        (24, r"\lim_{n \to \infty} \frac{a \cdot 2^{n+2}+1}{2^n+3} = 8\text{일 때, } a\text{의 값은?}", "2", ["1", "3", "4", "5"], r"$4a = 8 \implies a = 2$", ""),
        (25, r"\lim_{n \to \infty} \frac{6^n+2^n}{6^n+5^n}\text{의 값은?}", "1", ["0", "2", "3", "6"], r"극한값은 $1$입니다.", ""),
        (26, r"\lim_{n \to \infty} \frac{10^n-3^n}{10^n+7^n}\text{의 값은?}", "1", ["0", "2", "5", "10"], r"극한값은 $1$입니다.", ""),
        (27, r"\lim_{n \to \infty} \frac{2 \cdot 3^n + 1}{3^{n+1}-2}\text{의 값은?}", "\\frac{2}{3}", ["\\frac{1}{3}", "1", "\\frac{4}{3}", "2"], r"$$\frac{2}{3}$$", ""),
