    # ---------------------------------------------------------
    c4 = [
        (1, r"\sum_{n=1}^\infty \left(\frac{1}{2}\right)^n\text{의 값은?}", "1", ["\\frac{1}{4}", "\\frac{1}{2}", "2", "4"], r"첫째항 $\frac{1}{2}$, 공비 $\frac{1}{2}$이므로 $S = \frac{1/2}{1-1/2} = 1$", ""),
        (2, r"\sum_{n=1}^\infty \left(\frac{1}{3}\right)^n\text{의 값은?}", "\\frac{1}{2}", ["\\frac{1}{4}", "\\frac{1}{3}", "1", "\\frac{3}{2}"], r"$$S = \frac{1/3}{1-1/3} = \frac{1}{2}$$", ""),
        (3, r"\sum_{n=1}^\infty \frac{2}{3^n}\text{의 값은?}", "1", ["\\frac{1}{3}", "\\frac{2}{3}", "\\frac{4}{3}", "2"], r"$$S = \frac{2/3}{1-1/3} = 1$$", ""),
        (4, r"\sum_{n=1}^\infty \frac{3}{4^n}\text{의 값은?}", "1", ["\\frac{1}{2}", "\\frac{3}{4}", "\\frac{4}{3}", "2"], r"$$S = \frac{3/4}{1-1/4} = 1$$", ""),
        (5, r"\sum_{n=1}^\infty \left(\frac{2}{5}\right)^n\text{의 값은?}", "\\frac{2}{3}", ["\\frac{1}{3}", "1", "\\frac{4}{3}", "\\frac{5}{3}"], r"$$S = \frac{2/5}{1-2/5} = \frac{2}{3}$$", ""),
        (6, r"\sum_{n=1}^\infty (a_n - 3) = 5\text{일 때, } \lim_{n \to \infty} a_n\text{의 값은?}", "3", ["0", "1", "2", "5"], r"급수가 수렴하므로 일반항의 극한은 $0$입니다. 즉 $\lim (a_n-3) = 0 \implies \lim a_n = 3$", ""),
        (7, r"\sum_{n=1}^\infty \left(\frac{3}{4}\right)^n\text{의 값은?}", "3", ["1", "2", "4", "5"], r"2014학년도 모의평가: $\frac{3/4}{1-3/4} = 3$", "2014학년도 모의평가"),
        (8, r"\sum_{n=1}^\infty \frac{4}{5^n}\text{의 값은?}", "1", ["\\frac{1}{2}", "\\frac{4}{5}", "2", "\\frac{5}{4}"], r"2015학년도 모의평가: $\frac{4/5}{1-1/5} = 1$", "2015학년도 모의평가"),
        (9, r"\sum_{n=1}^\infty \frac{6}{7^n}\text{의 값을 구하시오.}", "1", [], r"2016학년도 모의평가: $\frac{6/7}{1-1/7} = 1$", "2016학년도 모의평가"),
        (10, r"\sum_{n=1}^\infty \frac{10}{11^n}\text{의 값을 구하시오.}", "1", [], r"2017학년도 수능: $\frac{10/11}{1-1/11} = 1$", "2017학년도 수능"),
        (11, r"\sum_{n=1}^\infty \frac{2^{n+1}}{3^n}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"2017학년도 모의평가: 첫째항 $\frac{4}{3}$, 공비 $\frac{2}{3} \implies \frac{4/3}{1/3} = 4$", "2017학년도 모의평가"),
        (12, r"\sum_{n=1}^\infty \frac{3 \cdot 2^n}{5^n}\text{의 값을 구하시오.}", "2", [], r"2018학년도 수능: 첫째항 $\frac{6}{5}$, 공비 $\frac{2}{5} \implies \frac{6/5}{3/5} = 2$", "2018학년도 수능"),
        (13, r"\sum_{n=1}^\infty \frac{1}{n(n+1)}\text{의 값은?}", "1", ["\\frac{1}{4}", "\\frac{1}{2}", "2", "\\infty"], r"부분분수 분해: $(1-1/2)+(1/2-1/3)+\cdots = 1$", ""),
        (14, r"\sum_{n=1}^\infty \frac{2}{n(n+2)}\text{의 값을 구하시오.}", "\\frac{3}{2}", [], r"$$\sum_{n=1}^\infty \left(\frac{1}{n}-\frac{1}{n+2}\right) = 1 + \frac{1}{2} = \frac{3}{2}$$", ""),
        (15, r"\sum_{n=1}^\infty (2a_n - 6) = 10\text{일 때, } \lim_{n \to \infty} a_n\text{의 값은?}", "3", ["0", "1", "2", "4"], r"$\lim (2a_n-6) = 0 \implies \lim a_n = 3$", ""),
        (16, r"\sum_{n=1}^\infty \frac{3^n+2^n}{4^n}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$\frac{3/4}{1/4} + \frac{2/4}{2/4} = 3 + 1 = 4$$", ""),
        (17, r"\sum_{n=1}^\infty ar^{n-1} = 4, a=2\text{일 때, 공비 } r\text{의 값은?}", "\\frac{1}{2}", ["\\frac{1}{4}", "\\frac{1}{3}", "\\frac{2}{3}", "\\frac{3}{4}"], r"$$\frac{2}{1-r} = 4 \implies 1-r = \frac{1}{2} \implies r = \frac{1}{2}$$", ""),
        (18, r"\sum_{n=1}^\infty \left(-\frac{1}{2}\right)^n\text{의 값은?}", "-\\frac{1}{3}", ["-1", "-\\frac{1}{2}", "\\frac{1}{3}", "\\frac{1}{2}"], r"$$S = \frac{-1/2}{1-(-1/2)} = \frac{-1/2}{3/2} = -\\frac{1}{3}$$", "")
    ]
    for p in c4:
        probs.append(make_problem(4, p[0], p[1], p[2], p[3], p[4], p[5]))

    # ---------------------------------------------------------
    # Chapter 5: 다항함수, 분수함수의 극한 (32 problems)
