        (3, r"\lim_{x \to 2} \frac{x^2-4}{x-2}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$\lim_{x \to 2} (x+2) = 4$$", ""),
        (4, r"\lim_{x \to 3} \frac{x^2-9}{x-3}\text{의 값은?}", "6", ["2", "3", "4", "5"], r"$$\lim_{x \to 3} (x+3) = 6$$", ""),
        (5, r"\lim_{x \to 1} \frac{x^2+2x-3}{x-1}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$\lim_{x \to 1} (x+3) = 4$$", ""),
        (6, r"\lim_{x \to 2} \frac{x^2-3x+2}{x-2}\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"$$\lim_{x \to 2} (x-1) = 1$$", ""),
        (7, r"\lim_{x \to 2} \frac{x^2-x-2}{x-2}\text{의 값은?}", "3", ["1", "2", "4", "5"], r"2013학년도 모의평가: $\lim_{x \to 2}(x+1) = 3$", "2013학년도 모의평가"),
        (8, r"\lim_{x \to 1} \frac{x^2+3x-4}{x-1}\text{의 값은?}", "5", ["2", "3", "4", "6"], r"2014학년도 수능: $\lim_{x \to 1}(x+4) = 5$", "2014학년도 수능"),
        (9, r"\lim_{x \to 3} \frac{x^2-x-6}{x-3}\text{의 값은?}", "5", ["2", "3", "4", "6"], r"2015학년도 모의평가: $\lim_{x \to 3}(x+2) = 5$", "2015학년도 모의평가"),
        (10, r"\lim_{x \to 2} \frac{x^2+2x-8}{x-2}\text{의 값은?}", "6", ["3", "4", "5", "7"], r"2016학년도 수능: $\lim_{x \to 2}(x+4) = 6$", "2016학년도 수능"),
        (11, r"\lim_{x \to 3} \frac{x^2+ax-12}{x-3} = b\text{일 때, } a+b\text{의 값을 구하시오.}", "8", [], r"2015학년도 모의평가: $9+3a-12=0 \implies a=1$. $\lim (x+4) = 7 = b$. $a+b=8$", "2015학년도 모의평가"),
        (12, r"\lim_{x \to 2} \frac{x^2-4}{x-2}\text{의 값을 구하시오.}", "4", [], r"2016학년도 모의평가: $4$", "2016학년도 모의평가"),
        (13, r"\lim_{x \to 1} \frac{x^2+ax-4}{x-1} = b\text{일 때, } ab\text{의 값을 구하시오.}", "15", [], r"2017학년도 수능: $1+a-4=0 \implies a=3$. $\lim (x+3) = 4 = b$. $ab = 12$", "2017학년도 수능"),
        (14, r"\lim_{x \to 2} \frac{x^3-8}{x-2}\text{의 값을 구하시오.}", "12", [], r"2017학년도 모의평가: $\lim (x^2+2x+4) = 12$", "2017학년도 모의평가"),
        (15, r"\lim_{x \to 1} \frac{x^2-1}{x-1}\text{의 값은?}", "2", ["0", "1", "3", "4"], r"2018학년도 모의평가: $\lim (x+1) = 2$", "2018학년도 모의평가"),
        (16, r"\lim_{x \to 3} \frac{x^2-2x-3}{x-3}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"2018학년도 수능: $\lim (x+1) = 4$", "2018학년도 수능"),
        (17, r"\lim_{x \to -1} \frac{x^2+3x+2}{x+1}\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"$$\lim_{x \to -1} (x+2) = 1$$", ""),
        (18, r"\lim_{x \to 2} \frac{x^2-5x+6}{x-2}\text{의 값을 구하시오.}", "-1", [], r"$$\lim_{x \to 2} (x-3) = -1$$", ""),
        (19, r"\lim_{x \to 4} \frac{x^2-16}{x-4}\text{의 값은?}", "8", ["2", "4", "6", "10"], r"$$\lim_{x \to 4} (x+4) = 8$$", ""),
        (20, r"\lim_{x \to 2} \frac{2x^2-3x-2}{x-2}\text{의 값은?}", "5", ["1", "2", "3", "4"], r"$$\lim_{x \to 2} (2x+1) = 5$$", ""),
        (21, r"\lim_{x \to 1} \frac{x^3-1}{x-1}\text{의 값은?}", "3", ["1", "2", "4", "5"], r"$$\lim_{x \to 1} (x^2+x+1) = 3$$", ""),
        (22, r"\lim_{x \to 3} \frac{x^2-9}{x-3}\text{의 값을 구하시오.}", "6", [], r"$$\lim_{x \to 3} (x+3) = 6$$", ""),
        (23, r"\lim_{x \to 2} \frac{x^2+ax-6}{x-2} = 5\text{일 때, 상수 } a\text{의 값은?}", "1", ["-1", "0", "2", "3"], r"$4+2a-6=0 \implies a=1$", ""),
        (24, r"\lim_{x \to 1} \frac{x^2+ax+b}{x-1} = 4\text{일 때, } a+b\text{의 값은?}", "1", ["-2", "-1", "0", "2"], r"$1+a+b=0 \implies b=-a-1$. $\lim (x+a+1) = a+2 = 4 \implies a=2, b=-3 \implies a+b=-1$", ""),
        (25, r"\lim_{x \to 2} \frac{x^2-4}{x^2-3x+2}\text{의 값은?}", "4", ["1", "2", "3", "5"], r"$$\lim_{x \to 2} \frac{x+2}{x-1} = \frac{4}{1} = 4$$", ""),
